<div class="gdp-range small text-muted"><span>Giáo viên phụ trách</span><span>Từ tiết</span><span>Đến tiết</span><span></span></div>
<div id="gdpRanges"><?php foreach($gdpRanges as$r): ?><div class="gdp-range"><select name="teacher[]" class="form-select form-select-sm" aria-label="Giáo viên" required><option value="">Chọn giáo viên</option><?php foreach($gdpTeachers as$t): ?><option value="<?=e($t['name'])?>" <?=$r['teacher']===$t['name']?'selected':''?>><?=e($t['name'])?></option><?php endforeach; ?></select><input name="from[]" type="number" min="1" max="35" step="1" class="form-control form-control-sm" aria-label="Từ tiết" required value="<?=e($r['from'])?>"><input name="to[]" type="number" min="1" max="35" step="1" class="form-control form-control-sm" aria-label="Đến tiết" required value="<?=e($r['to'])?>"><button type="button" class="btn btn-sm btn-outline-danger" data-remove aria-label="Bỏ dải tiết">×</button></div><?php endforeach; ?></div>
<button type="button" class="btn btn-sm btn-outline-primary" id="gdpAdd">+ Thêm dải tiết</button>
