<?php foreach($gdpConfigs as$c=>$config): ?><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 border-top py-2"><div><strong><?=e($c)?></strong> · <?=e($config['subject'])?><div class="small"><?php foreach($config['ranges']as$r): ?><span class="me-3"><?=e($r['teacher'])?>: <?=e($r['from'])?>–<?=e($r['to'])?> (<?=$r['to']-$r['from']+1?> tiết)</span><?php endforeach; ?></div></div><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="?program=1&amp;class=<?=urlencode($c)?>">Sửa / sao chép</a><form method="post" onsubmit="return confirm('Dùng lại các phân công GDĐP cũ của lớp này? TKB đã công bố không đổi.')"><input type="hidden" name="action" value="program_disable"><input type="hidden" name="csrf" value="<?=e($_SESSION['gdp_csrf'])?>"><input type="hidden" name="version_id" value="<?=e($gdpVersion)?>"><input type="hidden" name="fingerprint" value="<?=e(hash('sha256',json_encode($gdpConfigs)))?>"><input type="hidden" name="classes[]" value="<?=e($c)?>"><button class="btn btn-sm btn-outline-secondary">Dùng lại phân công cũ</button></form></div></div><?php endforeach; ?></div>
</div>
<script>
(()=>{const form=document.getElementById('gdpForm');if(!form)return;const rows=document.getElementById('gdpRanges'),template=rows.firstElementChild.cloneNode(true);function update(){const used=Array(36).fill(0);let invalid=false,teacherMissing=false;rows.querySelectorAll('.gdp-range').forEach(r=>{const a=Number(r.querySelector('[name="from[]"]').value),b=Number(r.querySelector('[name="to[]"]').value);if(!Number.isInteger(a)||!Number.isInteger(b)||a<1||b>35||a>b)invalid=true;else for(let p=a;p<=b;p++)used[p]++;if(!r.querySelector('select').value)teacherMissing=true;});const missing=[],duplicate=[];for(let p=1;p<=35;p++){if(!used[p])missing.push(p);if(used[p]>1)duplicate.push(p);}document.getElementById('gdpPeriods').replaceChildren(...used.slice(1).map((n,i)=>{const span=document.createElement('span');span.textContent=i+1;span.className=n===0?'missing':n>1?'duplicate':'';return span;}));const chosen=form.querySelectorAll('[name="classes[]"]:checked').length;document.getElementById('gdpCheck').textContent=`Đã giao ${35-missing.length}/35 tiết · ${chosen} lớp`+(duplicate.length?' · Trùng: '+duplicate.join(', '):'')+(missing.length?' · Thiếu: '+missing.join(', '):'')+(invalid?' · Kiểm tra dải tiết':'')+(teacherMissing?' · Chọn đủ giáo viên':'');document.getElementById('gdpSave').disabled=invalid||teacherMissing||!!missing.length||!!duplicate.length||!chosen;}form.addEventListener('input',update);form.addEventListener('change',update);rows.addEventListener('click',e=>{if(e.target.closest('[data-remove]')&&rows.children.length>1){e.target.closest('.gdp-range').remove();update();}});document.getElementById('gdpAdd').addEventListener('click',()=>{const r=template.cloneNode(true),last=rows.lastElementChild;const next=Math.min(35,Number(last.querySelector('[name="to[]"]').value)+1);r.querySelector('select').value='';r.querySelector('[name="from[]"]').value=next;r.querySelector('[name="to[]"]').value=35;rows.append(r);r.querySelector('select').focus();update();});update();})();
</script>
